// Deterministic fixture generator for module 04.
//
// Writes real (stored, method-0) zip archives that a `.mrpack` reader has to
// handle. No third-party dependency: the archive layout is written by hand and
// CRC-32 is the IEEE 802.3 polynomial, the same one zip uses.
//
// Usage: node tests/modules/04/make-fixtures.mjs [--check]
//   --check  fail if a committed fixture differs from the regenerated bytes

import { writeFileSync, readFileSync, mkdirSync, existsSync } from 'node:fs';
import { deflateRawSync } from 'node:zlib';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
export const FIXTURE_DIR = join(here, 'fixtures');

const CRC_TABLE = (() => {
  const table = new Uint32Array(256);
  for (let index = 0; index < 256; index += 1) {
    let value = index;
    for (let bit = 0; bit < 8; bit += 1) {
      value = value & 1 ? 0xedb88320 ^ (value >>> 1) : value >>> 1;
    }
    table[index] = value >>> 0;
  }
  return table;
})();

export function crc32(bytes) {
  let crc = 0xffffffff;
  for (const byte of bytes) {
    crc = (CRC_TABLE[(crc ^ byte) & 0xff] ^ (crc >>> 8)) >>> 0;
  }
  return (crc ^ 0xffffffff) >>> 0;
}

const LOCAL_SIGNATURE = 0x04034b50;
const CENTRAL_SIGNATURE = 0x02014b50;
const EOCD_SIGNATURE = 0x06054b50;

/**
 * Build a zip archive. Entries are stored (method 0) by default; with
 * `{ compress: true }` every non-empty entry is raw-deflated (method 8), which is
 * what real `.mrpack` archives and mod jars use.
 */
export function buildZip(entries, { compress = false } = {}) {
  const chunks = [];
  const central = [];
  let offset = 0;

  for (const entry of entries) {
    const name = Buffer.from(entry.name, 'utf8');
    const data = Buffer.isBuffer(entry.data) ? entry.data : Buffer.from(entry.data, 'utf8');
    const payload = compress && data.length > 0 ? deflateRawSync(data, { level: 9 }) : data;
    const method = payload === data ? 0 : 8;
    // `lies.size` / `lies.crc` produce a *deliberately* invalid archive so the reader
    // can be tested against corrupted payload metadata (D10/D15 challenges).
    const declaredSize = data.length + (entry.lieSizeDelta ?? 0);
    const crc = entry.forceCrc ?? crc32(data);

    const local = Buffer.alloc(30);
    local.writeUInt32LE(LOCAL_SIGNATURE, 0);
    local.writeUInt16LE(20, 4);
    local.writeUInt16LE(0, 6);
    local.writeUInt16LE(method, 8);
    local.writeUInt16LE(0, 10);
    local.writeUInt16LE(0, 12);
    local.writeUInt32LE(crc, 14);
    local.writeUInt32LE(payload.length, 18);
    local.writeUInt32LE(declaredSize, 22);
    local.writeUInt16LE(name.length, 26);
    local.writeUInt16LE(0, 28);

    chunks.push(local, name, payload);

    const header = Buffer.alloc(46);
    header.writeUInt32LE(CENTRAL_SIGNATURE, 0);
    header.writeUInt16LE(20, 4);
    header.writeUInt16LE(20, 6);
    header.writeUInt16LE(0, 8);
    header.writeUInt16LE(method, 10);
    header.writeUInt16LE(0, 12);
    header.writeUInt16LE(0, 14);
    header.writeUInt32LE(crc, 16);
    header.writeUInt32LE(payload.length, 20);
    header.writeUInt32LE(declaredSize, 24);
    header.writeUInt16LE(name.length, 28);
    header.writeUInt16LE(0, 30);
    header.writeUInt16LE(0, 32);
    header.writeUInt16LE(0, 34);
    header.writeUInt16LE(0, 36);
    header.writeUInt32LE(0, 38);
    header.writeUInt32LE(offset, 42);
    central.push(header, name);

    offset += local.length + name.length + payload.length;
  }

  const directory = Buffer.concat(central);
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(EOCD_SIGNATURE, 0);
  eocd.writeUInt16LE(0, 4);
  eocd.writeUInt16LE(0, 6);
  eocd.writeUInt16LE(entries.length, 8);
  eocd.writeUInt16LE(entries.length, 10);
  eocd.writeUInt32LE(directory.length, 12);
  eocd.writeUInt32LE(offset, 16);
  eocd.writeUInt16LE(0, 20);

  return Buffer.concat([...chunks, directory, eocd]);
}

export function buildStoredZip(entries) {
  return buildZip(entries, { compress: false });
}

const SHA1_A = 'a'.repeat(40);
const SHA1_B = 'b'.repeat(40);

export function sampleManifest() {
  return {
    formatVersion: 1,
    game: 'minecraft',
    versionId: '1.0.0',
    name: 'SHTMCL fixture pack',
    summary: 'Stored-zip fixture for the 04 modpack reader tests.',
    files: [
      {
        path: 'mods/sodium-0.5.3.jar',
        hashes: { sha1: SHA1_A, sha512: 'a'.repeat(128) },
        env: { client: 'required', server: 'unsupported' },
        downloads: ['https://example.invalid/sodium-0.5.3.jar'],
        fileSize: 1024,
      },
      {
        path: 'mods/lithium-0.11.2.jar',
        hashes: { sha1: SHA1_B },
        env: { client: 'required', server: 'required' },
        downloads: ['https://example.invalid/lithium-0.11.2.jar'],
        fileSize: 2048,
      },
    ],
    dependencies: { minecraft: '1.20.1', 'fabric-loader': '0.15.11' },
  };
}

export function sampleArchive() {
  return buildStoredZip([
    { name: 'modrinth.index.json', data: JSON.stringify(sampleManifest(), null, 2) },
    { name: 'overrides/config/sodium-options.json', data: '{"quality":"high"}' },
    { name: 'client-overrides/config/client-only.json', data: '{"keybinds":"default"}' },
    { name: 'server-overrides/config/server-only.json', data: '{"motd":"fixture"}' },
  ]);
}

/** Entry name escapes the archive root; the reader must refuse it. */
export function traversalArchive() {
  const manifest = sampleManifest();
  return buildStoredZip([
    { name: 'modrinth.index.json', data: JSON.stringify(manifest) },
    { name: 'overrides/../../evil.txt', data: 'pwned' },
  ]);
}

/** `name` and `versionId` are missing on purpose. */
export function incompleteArchive() {
  const manifest = sampleManifest();
  delete manifest.name;
  delete manifest.versionId;
  return buildStoredZip([{ name: 'modrinth.index.json', data: JSON.stringify(manifest) }]);
}

/** Same content as `sample.mrpack`, but every entry is deflated (method 8). */
export function deflatedArchive() {
  return buildZip(
    [
      { name: 'modrinth.index.json', data: JSON.stringify(sampleManifest(), null, 2) },
      { name: 'overrides/config/sodium-options.json', data: '{"quality":"high"}' },
      { name: 'client-overrides/config/client-only.json', data: '{"keybinds":"default"}' },
      { name: 'server-overrides/config/server-only.json', data: '{"motd":"fixture"}' },
    ],
    { compress: true },
  );
}

/** A pack with overrides: `overrides/` and `client-overrides/` (D1 acceptance). */
export function overridesArchive() {
  const manifest = sampleManifest();
  return buildStoredZip([
    { name: 'modrinth.index.json', data: JSON.stringify(manifest, null, 2) },
    { name: 'overrides/config/foo.txt', data: 'foo-value\n' },
    { name: 'overrides/config/nested/bar.json', data: '{ "bar": 1 }\n' },
    { name: 'client-overrides/config/client-only.json', data: '{ "keybinds": "default" }\n' },
    { name: 'server-overrides/config/server-only.json', data: '{ "motd": "fixture" }\n' },
  ]);
}

/** Override payload declares 6 more bytes than it carries: must be rejected (D10). */
export function truncatedOverrideArchive() {
  return buildStoredZip([
    { name: 'modrinth.index.json', data: JSON.stringify(sampleManifest()) },
    { name: 'overrides/config/foo.txt', data: 'foo-value\n', lieSizeDelta: 6 },
  ]);
}

/** Override payload with a zeroed CRC: must be rejected (D10). */
export function badCrcOverrideArchive() {
  return buildStoredZip([
    { name: 'modrinth.index.json', data: JSON.stringify(sampleManifest()) },
    { name: 'overrides/config/foo.txt', data: 'foo-value\n', forceCrc: 0 },
  ]);
}

/** Override targeting an NTFS alternate data stream: must be rejected (D15). */
export function adsOverrideArchive() {
  return buildStoredZip([
    { name: 'modrinth.index.json', data: JSON.stringify(sampleManifest()) },
    { name: 'overrides/mods/a.jar:stream', data: 'ads' },
  ]);
}

/** Two `modrinth.index.json` entries: must be rejected, not silently first-wins (D15). */
export function duplicateIndexArchive() {
  const first = sampleManifest();
  const second = { ...sampleManifest(), versionId: '9.9.9' };
  return buildStoredZip([
    { name: 'modrinth.index.json', data: JSON.stringify(first) },
    { name: 'modrinth.index.json', data: JSON.stringify(second) },
  ]);
}

export const FIXTURES = {
  'sample.mrpack': sampleArchive,
  'traversal.mrpack': traversalArchive,
  'incomplete.mrpack': incompleteArchive,
  'sample-deflate.mrpack': deflatedArchive,
  'overrides.mrpack': overridesArchive,
  'hostile-truncated-override.mrpack': truncatedOverrideArchive,
  'hostile-bad-crc.mrpack': badCrcOverrideArchive,
  'hostile-ads-override.mrpack': adsOverrideArchive,
  'hostile-duplicate-index.mrpack': duplicateIndexArchive,
};

export function writeFixtures() {
  mkdirSync(FIXTURE_DIR, { recursive: true });
  const written = [];
  for (const [name, build] of Object.entries(FIXTURES)) {
    const path = join(FIXTURE_DIR, name);
    writeFileSync(path, build());
    written.push(path);
  }
  return written;
}

export function checkFixtures() {
  const problems = [];
  for (const [name, build] of Object.entries(FIXTURES)) {
    const path = join(FIXTURE_DIR, name);
    if (!existsSync(path)) {
      problems.push(`${name}: missing`);
      continue;
    }
    const expected = build();
    const actual = readFileSync(path);
    if (!expected.equals(actual)) {
      problems.push(`${name}: differs from the generated bytes (${actual.length} vs ${expected.length})`);
    }
  }
  return problems;
}

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  if (process.argv.includes('--check')) {
    const problems = checkFixtures();
    if (problems.length > 0) {
      console.error(problems.join('\n'));
      process.exit(1);
    }
    console.log(`fixtures ok: ${Object.keys(FIXTURES).length} files`);
  } else {
    for (const path of writeFixtures()) {
      console.log(`wrote ${path}`);
    }
  }
}
